function close(){const prev=sel;sel=null;drawer.classList.remove("on");scrim.classList.remove("on");drawer.setAttribute("aria-hidden","true");render();const el=board.querySelector(`[data-id="${CSS.escape(prev)}"]`);el&&el.focus({preventScroll:true})}
