async function runQuery(raw){
  const my=++qSeq;const hits=new Map();const put=(id,role)=>{if(!id)return;if(!hits.has(id))hits.set(id,new Set());hits.get(id).add(role)};
  const ks=qKinds(raw);
  for(const [k,v] of ks){
    const hh=await hashOf(k,v);(IDX.h[hh]||[]).forEach(([ri,role])=>put(IDX.refs[ri][0],role));
    if(typeof ocrHitsIn==="function")ocrHitsIn(k,v,"").forEach(h=>put(h.id,h.role));
  }
  /* dossiês: busca por trecho (nome parcial, rua, observações), sem acento e sem pontuação nos números */
  const nq=normTxt(raw),dq=raw.replace(/\D/g,"");
  if(nq.length>=3&&typeof store!=="undefined")Object.values(store).forEach(o=>Object.entries(o.v||{}).forEach(([k,val])=>{
    if(!val||k[0]==="_"||typeof val!=="string")return;const nv=normTxt(val);
    if(nv.includes(nq)||(dq.length>=8&&val.replace(/\D/g,"").includes(dq)))put(o.id,`${typeof fieldName==="function"?fieldName(k):k} no dossiê ${o.v.numero||""}`.trim());
  }));
  if(my!==qSeq)return;
  qHits=hits;
  const vis=new Set(cases.filter(inPeriod).map(c=>c.id));
  qMeta={kinds:ks.map(x=>x[0]),n:hits.size,fora:[...hits.keys()].filter(id=>byId[id]&&!vis.has(id)).length};
  render();
}
function onQuery(val,src){
  q=val.trim().toUpperCase();if(src!=="q")$("q").value=val;if(src!=="q2")$("q2").value=val;
  if(!q){qHits=new Map();qMeta={kinds:[],n:0,fora:0};render();return}
  render();clearTimeout(qTimer);qTimer=setTimeout(()=>runQuery(val),180);
}
function qResHTML(){
  if(!q)return "";
  const list=filtered(),txt=list.filter(c=>c.search.includes(q)).length,ks=[...new Set(qMeta.kinds)].map(k=>Q_LABEL[k]);
  const items=[...qHits.entries()].filter(([id])=>byId[id]).slice(0,8);
  return `<div class="qres" role="status" aria-live="polite"><span class="qk">${ks.length?`Buscando por ${ks.join(" ou ")}`:"Busca por texto"}</span>
    <b>${list.length} caso${list.length===1?"":"s"}</b>${qMeta.fora?` <button class="linkbtn qall" type="button">+ ${qMeta.fora} fora do período · ver todos</button>`:""}
    ${items.length?`<div class="qitems">${items.map(([id,roles])=>`<button type="button" class="qit" data-qgo="${esc(id)}"><span class="plate sm">${esc(byId[id].plate)}</span><span>${esc([...roles].slice(0,2).join(" · "))}</span></button>`).join("")}</div>`:""}
    ${!list.length&&!qMeta.fora?`<span class="qnone">Nada encontrado. CPF, telefone, e-mail e nome precisam estar completos; placa pode ser parcial.</span>`:""}</div>`;
}
