function initPads(){
  document.querySelectorAll("canvas.pad").forEach(cv=>{
    const k=cv.dataset.sig,ctx2=cv.getContext("2d");
    ctx2.lineWidth=4;ctx2.lineCap="round";ctx2.lineJoin="round";ctx2.strokeStyle="#1b1d4a";
    if(cur.img[k]){const im=new Image();im.onload=()=>ctx2.drawImage(im,0,0,cv.width,cv.height);im.src=imgSrc(cur.img[k])}
    let drawing=false,last=null,dirty=false;
    const pos=e=>{const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]};
    cv.addEventListener("pointerdown",e=>{if(cur.v[k+"_mode"]==="typed")return;drawing=true;last=pos(e);cv.setPointerCapture(e.pointerId);ctx2.beginPath();ctx2.arc(last[0],last[1],2,0,7);ctx2.fillStyle="#1b1d4a";ctx2.fill();dirty=true});
    cv.addEventListener("pointermove",e=>{if(!drawing)return;const p=pos(e);ctx2.beginPath();ctx2.moveTo(last[0],last[1]);ctx2.lineTo(p[0],p[1]);ctx2.stroke();last=p;dirty=true});
    const end=()=>{if(!drawing)return;drawing=false;if(dirty){cur.img[k]=cv.toDataURL("image/png");const at=new Date().toLocaleString("pt-BR",{timeZone:"America/Sao_Paulo",dateStyle:"short",timeStyle:"short"});cur.v[k+"_at"]=at;$("sa-"+k).textContent="Assinado em "+at;persistCur()}};
    cv.addEventListener("pointerup",end);cv.addEventListener("pointercancel",end);
  });
}
