/* ---------- estado do editor ---------- */
let cur=null; /* {id, v:{}, n:{}, img:{}, st, created, updated} */
const linkState={}; /* fieldKey -> [{ref, role, kind, txt, strong}] */
const mentionState={}; /* fieldKey -> {tokens:[{kind,v,raw,hits:[...]}]} */
function ctxFor(id){
  const c=byId[id]&&byId[id].src!=="metabase"?byId[id]:null;const m=IDX.mb[id]||null;const ri=REF_BY_ID[id];const ref=ri!=null?IDX.refs[ri]:null;
  const plate=c?c.plate:ref?ref[1]:id.split("-")[0];const date=c?c.date:ref?ref[2]:id.split("-").slice(1).join("-");
  return {id,c,m,plate,date};
}
function newDossier(id){
  const ctx=ctxFor(id);const yr=new Date().getFullYear();const n=Object.keys(store).length+1;
  ctx.num=`DOS-${yr}-${String(n).padStart(3,"0")}`;
  const d={id,v:{},n:{},img:{},src:{},st:"draft",created:Date.now(),updated:Date.now()};
  SCHEMA.forEach(s=>s.b.forEach(b=>{
    (b.f||[]).forEach(f=>{if(f.pf){const v=f.pf(ctx);if(v){d.v[f.k]=String(v);const s=f.src||(["numero","data_dossie","placa","placa2"].includes(f.k)?"":"Planilha");if(s)d.src[f.k]=s}}});
    if(b.tbl&&b.pf){const o=b.pf(ctx);Object.entries(o).forEach(([k,v])=>{if(v)d.v[b.tbl+"."+k]=String(v)})}
    if(b.tbl&&b.dyn)d.n[b.tbl]=typeof b.dyn==="number"?b.dyn:1;
  }));
  /* pagamentos de terceiros conhecidos pela planilha */
  if(ctx.c&&isYes(sc(ctx,48))){d.v["pagtos.0.4"]=/charge/i.test(sc(ctx,48))?"Cartão":"PIX";const cx=sc(ctx,49);d.v["pagtos.0.5"]=/cau/i.test(cx)?"Caução":/fat/i.test(cx)?"Fatura":"";d.v["pagtos.0.6"]=yn(sc(ctx,52))}
  store[id]=d;saveStore();
  if(byId[id]&&phaseOf(byId[id])==="novo"){setPhase(id,"andamento")}
  return d;
}
function openDossier(id){
  if(!store[id])newDossier(id);
  cur=store[id];showView("dos");$("dosEd").hidden=false;document.body.classList.add("editing");
  Object.keys(linkState).forEach(k=>delete linkState[k]);Object.keys(mentionState).forEach(k=>delete mentionState[k]);
  renderEditor();checkAll(false);
  if(typeof mbBar==="function"){mbBar("mbBar","");if(!cur.v._mb_at||cur.v._mb_v!==MB_VER)setTimeout(()=>mbFillDossier(true),300)}
}
var showView=function(v){
  $("nav-casos").classList.toggle("on",v==="casos");$("nav-dos").classList.toggle("on",v==="dos");$("nav-ana").classList.toggle("on",v==="ana");$("nav-docs").classList.toggle("on",v==="docs");
  $("caseView").hidden=v!=="casos";$("dosView").hidden=v!=="dos";$("anaView").hidden=v!=="ana";$("docView").hidden=v!=="docs";
  document.querySelector(".app").classList.toggle("dos-mode",v!=="casos");
};

