var isNA=k=>cur&&cur.v[k+"_na"]==="1";
var reqDone=r=>r.sig?!!(cur.img[r.k]||cur.v[r.k+"_text"]):!!(String(cur.v[r.k]||"").trim()||isNA(r.k));
