async function saveDocOcr(docId,d){try{await DB.doc("docs/"+docId).update({ocr:{tipo:d.tipo||"",resumo:d.resumo||"",bo:d.bo||{},text:(d.text||"").slice(0,20000),tokens:(d.tokens||[]).slice(0,200),locais:(d.locais||[]).slice(0,20),mode:d.mode||"",at:Date.now()},ocrState:"done"})}catch(e){}}
