      for(let la=Math.floor((cmy-H0/2/sc)/stepDeg)*stepDeg;la<cmy+H0/2/sc;la+=stepDeg){const yy=H0/2-(la-cmy)*sc;g2.beginPath();g2.moveTo(0,yy);g2.lineTo(W0,yy);g2.stroke()}
