const safeId=id=>id.replace(/[^A-Za-z0-9]/g,"_");
const NAMES={};let namesAsked=new Set();
function personName(uid){if(!uid)return "";if(uid===myId)return "você";if(NAMES[uid])return NAMES[uid];if(USER&&USER.profiles&&!namesAsked.has(uid)){namesAsked.add(uid);USER.profiles([uid]).then(ps=>{const n=ps&&ps[uid]&&ps[uid].name;NAMES[uid]=n||"outra pessoa";if(typeof ddListVisible==="function"?ddListVisible():$("dosDrawer").classList.contains("on"))renderList();if(cur&&!$("dosEd").hidden)$("edSub")&&renderEditorSub()}).catch(()=>{NAMES[uid]="outra pessoa"})}return NAMES[uid]||"outra pessoa"}
