async function initSync(){
  if(!DB)return;
  let firstD=true,firstC=true;
  DB.collection("dossies").limit(1000).onSnapshot(snap=>{
    let changed=false;snap.docs.forEach(d=>{if(applyRemoteDossier(d.data()))changed=true});
    snap.docChanges().forEach(ch=>{if(ch.type==="removed"){const id=ch.doc.data().caseId;if(id&&store[id]&&!pending.has(id)){delete store[id];delete lastSynced[id];changed=true;if(cur&&cur.id===id&&!$("dosEd").hidden){toast("Este dossiê foi excluído por outra pessoa.");$("edBack").click()}}}});
    if(firstD&&!snap.metadata.fromCache){firstD=false;syncOn=true;
      const localOnly=Object.keys(store).filter(id=>!lastSynced[id]);if(localOnly.length){toast(`Enviando ${localOnly.length} dossiê${localOnly.length>1?"s":""} deste navegador para o banco compartilhado…`);scheduleSync()}}
    if(changed){try{localStorage.setItem("dossies-v1",JSON.stringify(store))}catch(e){}if(typeof ddListVisible==="function"?ddListVisible():$("dosDrawer").classList.contains("on"))renderList();if(!$("caseView").hidden&&!dragId)render()}
  },e=>{badge("Banco indisponível","warn")});
  DB.collection("casos").limit(1000).onSnapshot(snap=>{
    let changed=false;snap.docs.forEach(d=>{if(applyRemoteCase(d.data()))changed=true});
    if(firstC&&!snap.metadata.fromCache){firstC=false;cases.forEach(c=>{if(!lastCase[c.id]){const orig=g(c.r,60);const o=isYes(orig)?"Sim":isNo(orig)?"Não":"Em análise";if(c.note||c.phase||c.cancel||c.ind!==o)scheduleCaseSync()}})}
    if(changed){persistLocalOnly();if(!$("caseView").hidden&&!dragId)render();if(sel!==null&&!cancelOpen&&document.activeElement!==$("note"))renderDrawer()}
  },()=>{});
}
function persistLocalOnly(){try{const s={};cases.forEach(c=>{const orig=g(c.r,60);const o=isYes(orig)?"Sim":isNo(orig)?"Não":"Em análise";if(c.note||c.ind!==o||c.phase||c.cancel)s[c.id]={ind:c.ind,note:c.note,phase:c.phase,phHist:c.phHist,cancel:c.cancel}});localStorage.setItem("dossie-v2",JSON.stringify(s))}catch(e){}}

/* =================== ANALYTICS =================== */
