  tempo:v=>{const n=parseInt(v,10);if(isNaN(n))return "";return n<=7?"Até 7 dias":n<=15?"8 a 15 dias":n<=30?"16 a 30 dias":n<=60?"31 a 60 dias":n<=90?"61 a 90 dias":n<=180?"91 a 180 dias":"Mais de 180 dias"},
  km:v=>{const n=parseInt(String(v).replace(/\D/g,""),10);if(isNaN(n)||n===0)return "";return n<100?"Menos de 100 km":n<150?"100 a 149 km":n<200?"150 a 199 km":n<250?"200 a 249 km":"250 km ou mais"},
  idade:v=>{v=(v||"").replace(/\s+/g," ").trim();const m=v.match(/(\d+)\D+(\d+)/);if(m)return `${m[1]} a ${m[2]} anos`;const n=v.match(/\d+/);return n?(/acima|mais|\+/i.test(v)?`Acima de ${n[0]} anos`:`${n[0]} anos`):""},
