/* ---- desenho ---- */
var redeZoom=null;
function redeLayout(nodes,links,W,H){
  const par=new Map(nodes.map(n=>[n.k,n.k]));const f=k=>{while(par.get(k)!==k){par.set(k,par.get(par.get(k)));k=par.get(k)}return k};
  links.forEach(l=>{const a=f(l.source.k),b=f(l.target.k);if(a!==b)par.set(a,b)});
  const comps=new Map();nodes.forEach(n=>{const r=f(n.k);(comps.get(r)||comps.set(r,[]).get(r)).push(n)});
  const boxes=[...comps.values()].map(ns=>{const set=new Set(ns);const ls=links.filter(l=>set.has(l.source));
    ns.forEach((n,i)=>{const a=i*2.4;n.x=Math.cos(a)*(20+i*6);n.y=Math.sin(a)*(20+i*6)});
    if(ns.length>1){const sim=d3.forceSimulation(ns).force("link",d3.forceLink(ls).distance(l=>l.source.t==="p"&&l.target.t==="p"?200:l.source.t==="p"||l.target.t==="p"?105:60).strength(.7))
      .force("charge",d3.forceManyBody().strength(n=>n.t==="p"?-700:-90)).force("collide",d3.forceCollide(n=>n.t==="p"?92:16).strength(.9))
      .force("x",d3.forceX(0).strength(.06)).force("y",d3.forceY(0).strength(.09)).stop();for(let i=0,T=Math.min(320,120+ns.length*2);i<T;i++)sim.tick()}
    const hw=n=>n.t==="p"?90:60,hh=n=>n.t==="p"?36:14;
    const x0=Math.min(...ns.map(n=>n.x-hw(n))),x1=Math.max(...ns.map(n=>n.x+hw(n))),y0=Math.min(...ns.map(n=>n.y-hh(n))),y1=Math.max(...ns.map(n=>n.y+hh(n)));
    return {ns,x0,y0,w:x1-x0,h:y1-y0}});
  boxes.sort((a,b)=>b.ns.length-a.ns.length);
  const area=boxes.reduce((s,b)=>s+(b.w+40)*(b.h+40),0),rowW=Math.max(boxes[0]?boxes[0].w:0,Math.sqrt(area*(W/H))*1.05);
  let x=0,y=0,rh=0;const GAP=40;
  boxes.forEach(b=>{if(x>0&&x+b.w>rowW){x=0;y+=rh+GAP;rh=0}const dx=x-b.x0,dy=y-b.y0;b.ns.forEach(n=>{n.x+=dx;n.y+=dy});x+=b.w+GAP;rh=Math.max(rh,b.h)});
}
/* rede do caso em anéis: centro, 1º anel agrupado por tipo de vínculo, 2º anel com os outros casos */
function redeLayoutEgo(nodes,edges,c0){
  const byK=new Map(nodes.map(n=>[n.k,n]));c0.x=0;c0.y=0;
  const ek=k=>{const e=edges.find(e=>(e.s===c0.k&&e.t===k)||(e.t===c0.k&&e.s===k));return e?RK_ORDER.indexOf([...e.kinds].sort((a,b)=>RK_ORDER.indexOf(a)-RK_ORDER.indexOf(b))[0]):9};
  const l1=nodes.filter(n=>n.lv===1).sort((a,b)=>ek(a.k)-ek(b.k)||(b.alert-a.alert)||(a.t<b.t?-1:1));
  const arc=n=>n.t==="p"?200:Math.max(64,Math.min(150,(n.name||"").split(" ").slice(0,2).join(" ").length*6.4+30));
  const tot=l1.reduce((s,n)=>s+arc(n),0),r1=Math.max(190,tot/(2*Math.PI));
  let acc=0;l1.forEach(n=>{const a=-Math.PI/2+2*Math.PI*(acc+arc(n)/2)/Math.max(tot,1);acc+=arc(n);n.a=a;n.x=Math.cos(a)*r1;n.y=Math.sin(a)*r1});
  const l2=nodes.filter(n=>n.lv===2);const r2=r1+Math.max(230,l2.length*205/(2*Math.PI)-r1+60);
  l2.forEach(n=>{const ps=edges.filter(e=>e.s===n.k||e.t===n.k).map(e=>byK.get(other(e,n.k))).filter(p=>p&&p.lv===1);
    const sx=ps.reduce((s,p)=>s+Math.cos(p.a),0),sy=ps.reduce((s,p)=>s+Math.sin(p.a),0);n.a=Math.atan2(sy,sx)});
  l2.sort((a,b)=>a.a-b.a);const minA=205/r2;
  for(let it=0;it<40;it++){let moved=false;for(let i=1;i<l2.length;i++){const d=l2[i].a-l2[i-1].a;if(d<minA){const m=(minA-d)/2;l2[i].a+=m;l2[i-1].a-=m;moved=true}}if(!moved)break}
  l2.forEach(n=>{n.x=Math.cos(n.a)*r2;n.y=Math.sin(n.a)*r2});
  /* acomoda: centro fixo, cada anel puxado para o seu raio, outros casos perto de quem os liga */
  c0.fx=0;c0.fy=0;
  const ls=edges.map(e=>({source:byK.get(e.s),target:byK.get(e.t)})).filter(l=>l.source&&l.target);
  const sim=d3.forceSimulation(nodes)
    .force("link",d3.forceLink(ls).distance(l=>(l.source.lv===0||l.target.lv===0)?r1:170).strength(l=>(l.source.lv===0||l.target.lv===0)?.05:.5))
    .force("r",d3.forceRadial(n=>n.lv===0?0:n.lv===1?r1:r2,0,0).strength(n=>n.lv===1?.9:.25))
    .force("charge",d3.forceManyBody().strength(n=>n.t==="p"?-260:-60))
    .force("collide",d3.forceCollide(n=>n.t==="p"?(n.lv===0?110:94):n.t==="m"?52:42).strength(1)).stop();
  for(let i=0;i<300;i++)sim.tick();
  c0.fx=c0.fy=null;nodes.forEach(n=>{n.a=Math.atan2(n.y,n.x)});
  return {x:0,y:0,w:2*(l2.length?r2+100:r1+120),h:2*(l2.length?r2+50:r1+40)};
}
