  const B=root.append("g").selectAll("g").data(nodes.filter(n=>n.t==="b")).join("g").attr("class",n=>"rb"+(n.alert?" al":"")+(n.st==="BANNED"?" ban":"")+(n.drv?"":" nd")+(n.shared?" sh":"")).attr("tabindex",0).attr("role","button").attr("aria-label",n=>`${n.name||"Sem nome"}${n.st?", "+rStatus(n.st):""}`);
