  const dossies=Object.values(store).sort((a,b)=>(b.updated||0)-(a.updated||0));
  const rasc=dossies.filter(d=>d.st!=="done").length;
  const h=new Date().getHours(),saud=h<12?"Bom dia":h<18?"Boa tarde":"Boa noite";
