/* ---------- Busca geral + Perguntar ao Claude ---------- */
var PLATE_RX=/\b(?!DOS-?20\d\d)([A-Z]{3}-?\d[A-Z0-9]\d{2})\b(?!-\d)/gi;
var gsNorm=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toUpperCase();
function gsDossierText(d){return Object.entries(d.v||{}).filter(([k,v])=>v&&!/^_|_at$|_mode$|_na$/.test(k)&&typeof v==="string"&&v.length<2000).map(([k,v])=>v).join(" ")}
function gsResults(q){
  const Q=gsNorm(q).trim();if(Q.length<2)return {cases:[],dos:[],docs:[]};
  const Qd=Q.replace(/\D/g,""),Qp=Q.replace(/[^A-Z0-9]/g,"");
  const hit=s=>{const S=gsNorm(s);return S.includes(Q)||(Qd.length>=5&&S.replace(/\D/g,"").includes(Qd))};
  const cs=cases.filter(c=>(Qp.length>=3&&c.plate.replace(/[^A-Z0-9]/g,"").includes(Qp))||hit([c.plate,c.model,c.base,(OCC[c.occ]||[c.occ])[0],c.alerta,c.obs,c.date].join(" "))||(typeof qHits!=="undefined"&&qHits.has&&qHits.has(c.id)&&q===window.__gsLastQ)).sort((a,b)=>b.sort.localeCompare(a.sort)).slice(0,6);
  const ds=Object.values(store).filter(d=>{const c=ctxFor(d.id);return hit([c.plate,d.v&&d.v.numero,gsDossierText(d)].join(" "))}).sort((a,b)=>(b.updated||0)-(a.updated||0)).slice(0,5);
  const dc=(typeof docsCache!=="undefined"?docsCache:[]).filter(d=>hit([d.name,d.plate,d.dossie,d.categoria,d.ocr&&d.ocr.tipo,d.ocr&&d.ocr.resumo,d.ocr&&d.ocr.text].join(" "))).slice(0,5);
  return {cases:cs,dos:ds,docs:dc}}
var GS={sel:0,items:[]};
function gsRender(){
  const q=$("gsq").value,box=$("gsr");const R=gsResults(q);const it=[];
  if(q.trim().length>=2)it.push({t:"ask",q});
  R.cases.forEach(c=>it.push({t:"case",c}));R.dos.forEach(d=>it.push({t:"dos",d}));R.docs.forEach(d=>it.push({t:"doc",d}));
  GS.items=it;GS.sel=Math.min(GS.sel,Math.max(0,it.length-1));
  if(!q.trim()){box.hidden=true;return}
  const sec=(title,html)=>html?`<div class="gs-sec">${title}</div>${html}`:"";let i=0;
  const row=(inner,cls="")=>`<button type="button" class="gs-it${cls}${i===GS.sel?" on":""}" data-gs="${i++}" role="option">${inner}</button>`;
  const ask=it[0]&&it[0].t==="ask"?row(`<span class="gs-ai">${AI_I}</span><span class="gs-tx"><b>Perguntar ao Claude</b><span>“${esc(q.trim())}”</span></span><kbd>Enter</kbd>`," ask"):"";
  const cH=R.cases.map(c=>{const o=OCC[c.occ]||[c.occ||"Sem tipo","var(--fg-3)"];return row(`<span class="plate">${esc(c.plate)}</span><span class="gs-tx"><b>${c.date} · ${esc(c.base)}</b><span>${esc(c.model||"Modelo não informado")} · ${PH_ONE[phaseOf(c)]}</span></span><span class="occ" style="--oc:${o[1]};background:${o[2]||"var(--surface-2)"}">${o[0]}</span>`)}).join("");
  const dH=R.dos.map(d=>{const c=ctxFor(d.id);return row(`<span class="gs-ic">${homeIcon("nav-dos")}</span><span class="gs-tx"><b>${esc(d.v&&d.v.numero||"Dossiê")} · ${esc(c.plate||"")}</b><span>${d.st==="done"?"Finalizado":"Rascunho"}${d.v&&d.v.nome?" · "+esc(d.v.nome):""}</span></span>`)}).join("");
  const fH=R.docs.map(d=>row(`<span class="gs-ic">${homeIcon("nav-docs")}</span><span class="gs-tx"><b>${esc(d.name)}</b><span>${esc(d.categoria||"")}${d.plate?" · "+esc(d.plate):""}${d.ocr&&d.ocr.resumo?" · "+esc(d.ocr.resumo.slice(0,80)):""}</span></span>`)).join("");
  box.innerHTML=ask+sec("Casos",cH)+sec("Dossiês",dH)+sec("Documentos",fH)+(R.cases.length+R.dos.length+R.docs.length?"":`<div class="gs-none">Nada encontrado em casos, dossiês ou documentos. Pergunte ao Claude.</div>`);
  box.hidden=false}
function gsGo(i){const x=GS.items[i];if(!x)return;gsClose();
  if(x.t==="ask")askOpen(x.q);
  else if(x.t==="case"){if(sel!==null)close();showView("casos");render();open(x.c.id)}
  else if(x.t==="dos")openDossier(x.d.id);
  else if(x.t==="doc"){$("nav-docs").click();const inp=$("docQ");inp.value=x.d.name;inp.dispatchEvent(new Event("input"))}}
function gsClose(){$("gsr").hidden=true}
/* ---- Claude ---- */
var AI_I='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 3l1.8 4.7L18.5 9.5l-4.7 1.8L12 16l-1.8-4.7L5.5 9.5l4.7-1.8z"/><path d="M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z"/></svg>';
var ASK={msgs:[],busy:false,ctrl:null};
function caseLine(c){const m=typeof mbLive!=="undefined"&&mbLive[c.id];return [c.plate,c.date,c.base,(OCC[c.occ]||[c.occ||"sem tipo"])[0],PH_ONE[phaseOf(c)],"indícios do driver: "+c.ind,c.flags.length?"sinais: "+c.flags.join("/"):"",c.model,m&&+m.aberto>0?"débito "+m.aberto:"",m&&m.driver_status?"motorista "+m.driver_status:"",store[c.id]?"dossiê "+(store[c.id].st==="done"?"finalizado":"rascunho"):""].filter(Boolean).join(" | ")}
function askOverview(){
  const ph={};cases.forEach(c=>{const k=phaseOf(c);ph[k]=(ph[k]||0)+1});
  const ds=Object.values(store),docs=typeof docsCache!=="undefined"?docsCache:[];
  return `Hoje é ${new Date().toLocaleDateString("pt-BR",{timeZone:"America/Sao_Paulo"})}. O app tem ${cases.length} casos de perda (${Object.entries(ph).map(([k,v])=>PH_ONE[k]+": "+v).join(", ")}), ${ds.length} dossiês (${ds.filter(d=>d.st==="done").length} finalizados) e ${docs.length} documentos anexados.
Lista de casos (placa | data da perda | base | ocorrência | fase | indícios | sinais | modelo | ...):
${cases.slice().sort((a,b)=>b.sort.localeCompare(a.sort)).map(caseLine).join("\n")}`}
var caseByPlate=p=>{const P=String(p||"").toUpperCase().replace(/[^A-Z0-9]/g,"");return cases.filter(c=>c.plate.replace(/[^A-Z0-9]/g,"")===P)};
var ASK_TOOLS=[
 {name:"detalhes_caso",description:"Todos os dados de planilha e Metabase de um caso de perda, pela placa. Use antes de afirmar qualquer coisa específica de um caso.",inputSchema:{type:"object",properties:{placa:{type:"string"}},required:["placa"]},
  execute:({placa})=>{const L=caseByPlate(placa);if(!L.length)return {erro:"Placa não encontrada nos casos"};return L.map(c=>({caso:caseLine(c),campos:Object.fromEntries(Object.entries(LBL).map(([k,l])=>[l,g(c.r,+k)]).filter(([l,v])=>v&&!/^[\s\-–]*$/.test(v))),obs:c.obs||"",nota:c.note||"",vinculos:c.links.filter(l=>l.strong).map(l=>l.o+": "+l.ls.slice(0,3).join("; ")),metabase:(typeof mbLive!=="undefined"&&mbLive[c.id])||null}))}},
 {name:"dossie",description:"Campos preenchidos do dossiê de um caso, pela placa (relato, locatário, financeiro, pós-perda, indícios, conclusão).",inputSchema:{type:"object",properties:{placa:{type:"string"}},required:["placa"]},
  execute:({placa})=>{const L=caseByPlate(placa).map(c=>store[c.id]).filter(Boolean);if(!L.length)return {erro:"Não há dossiê para esta placa"};
   return L.map(d=>({numero:d.v.numero||"",status:d.st==="done"?"finalizado":"rascunho",campos:Object.fromEntries(Object.entries(d.v).filter(([k,v])=>v&&typeof v==="string"&&!/^_|_at$|_mode$|_text$/.test(k)).map(([k,v])=>[fieldName(k)+(/\.\d+\.\d+$/.test(k)?" ["+k+"]":""),k.endsWith("_na")?"Não se aplica":v.slice(0,1500)]))}))}},
 {name:"documentos",description:"Documentos anexados (nome, categoria, resumo e texto lido por OCR). Filtre por placa ou deixe vazio para listar todos.",inputSchema:{type:"object",properties:{placa:{type:"string"}}},
  execute:({placa})=>{const P=String(placa||"").toUpperCase().replace(/[^A-Z0-9]/g,"");const L=(typeof docsCache!=="undefined"?docsCache:[]).filter(d=>!P||String(d.plate||"").replace(/[^A-Z0-9]/g,"")===P);
   return L.slice(0,25).map(d=>({nome:d.name,categoria:d.categoria||"",placa:d.plate||"",tipo:d.ocr&&d.ocr.tipo||"",resumo:d.ocr&&d.ocr.resumo||"",texto:d.ocr&&d.ocr.text?String(d.ocr.text).slice(0,P?4000:600):""}))}}];
function askSys(){return `Você é o assistente do app KovInt (locadora de veículos), usado pelo time de investigação de perdas (furto, roubo, apropriação e estelionato).
Responda em português do Brasil, direto e curto, com base SOMENTE nos dados abaixo e no que as ferramentas devolverem. Use as ferramentas para detalhes de um caso, do dossiê ou dos documentos. Cite as placas. Se a informação não estiver nos dados, diga que não encontrou em vez de supor. Não exponha CPF completo nem dados pessoais além do necessário para responder. Formate com listas curtas e **negrito** quando ajudar.

${askOverview()}`}
function mdLite(s){let h=esc(s);h=h.replace(/\*\*(.+?)\*\*/g,"<b>$1</b>").replace(/`([^`]+)`/g,"<code>$1</code>");
  const lines=h.split("\n");let out="",ul=false;lines.forEach(l=>{const m=l.match(/^\s*[-*•]\s+(.*)/);if(m){if(!ul){out+="<ul>";ul=true}out+=`<li>${m[1]}</li>`}else{if(ul){out+="</ul>";ul=false}out+=l.trim()?`<p>${l}</p>`:""}});if(ul)out+="</ul>";
  return out.replace(/\b([A-Z]{3}\d[A-Z0-9]\d{2})\b/g,(x)=>caseByPlate(x).length?`<button type="button" class="ask-plate" data-askplate="${x}">${x}</button>`:x)}
function askPaint(){const b=$("askBody");b.innerHTML=ASK.msgs.map(m=>m.role==="user"?`<div class="ask-q">${esc(m.content)}</div>`:`<div class="ask-a${m.err?" err":""}">${m.content?mdLite(m.content):'<span class="ask-think"><i></i><i></i><i></i> Pensando…</span>'}</div>`).join("")||`<div class="ask-empty"><b>Pergunte sobre casos, dossiês e documentos</b><span>Ex.: "Quais casos de outubro tiveram PIX de terceiros?", "Resuma o dossiê da RNK2H48", "Que documentos temos da TWY7E15?"</span></div>`;b.scrollTop=b.scrollHeight}
async function askSend(q){q=String(q||"").trim();if(!q||ASK.busy)return;
  const sample=window.claude&&window.claude.use?await window.claude.use("sample"):null;
  ASK.msgs.push({role:"user",content:q});const ans={role:"assistant",content:""};ASK.msgs.push(ans);askPaint();
  if(!sample){ans.content="O Claude só responde com o app aberto no claude.ai.";ans.err=1;askPaint();return}
  ASK.busy=true;$("askIn").disabled=true;$("askSend").disabled=true;ASK.ctrl=new AbortController();
  const hist=ASK.msgs.slice(0,-1).map((m,i)=>({role:m.role,content:i===0?askSys()+"\n\nPergunta: "+m.content:m.content}));
  try{const r=await sample(hist,{tools:ASK_TOOLS,signal:ASK.ctrl.signal,cache:false,onText:({text})=>{ans.content=text;askPaint()}});ans.content=r.text||ans.content||"Sem resposta."}
  catch(e){ans.err=1;ans.content=e&&e.code==="not_granted"?"O acesso ao Claude não foi liberado para este app.":e&&e.code==="rate_limited"?"Muitas perguntas seguidas. Espere alguns segundos e tente de novo.":e&&e.code==="cancelled"?(ans.content||"Pergunta cancelada."):"O Claude não conseguiu responder agora"+(e&&e.code?` (${e.code})`:"")+"."}
  ASK.busy=false;$("askIn").disabled=false;$("askSend").disabled=false;askPaint();$("askIn").focus()}
function askOpen(q){$("askp").hidden=false;document.body.classList.add("ask-open");askPaint();if(q)askSend(q);setTimeout(()=>$("askIn").focus(),40)}
function askClose(){$("askp").hidden=true;document.body.classList.remove("ask-open");if(ASK.ctrl&&ASK.busy)ASK.ctrl.abort()}
(function(){
  const q=$("gsq");
  q.addEventListener("input",()=>{GS.sel=0;gsRender()});
  q.addEventListener("focus",()=>{if(q.value.trim())gsRender()});
  q.addEventListener("keydown",e=>{
    if(e.key==="ArrowDown"){e.preventDefault();GS.sel=Math.min(GS.sel+1,GS.items.length-1);gsRender()}
    else if(e.key==="ArrowUp"){e.preventDefault();GS.sel=Math.max(GS.sel-1,0);gsRender()}
    else if(e.key==="Enter"){e.preventDefault();if(GS.items.length)gsGo(GS.sel)}
    else if(e.key==="Escape"){gsClose();q.blur()}});
  $("gsr").addEventListener("mousedown",e=>e.preventDefault());
  $("gsr").addEventListener("click",e=>{const b=e.target.closest("[data-gs]");if(b){gsGo(+b.dataset.gs);q.value=""}});
  document.addEventListener("mousedown",e=>{if(!e.target.closest(".gsearch"))gsClose()});
  document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();q.focus();q.select()}});
  $("askForm").addEventListener("submit",e=>{e.preventDefault();const v=$("askIn").value;$("askIn").value="";askSend(v)});
  $("askp").addEventListener("click",e=>{if(e.target.closest("[data-askclose]")){askClose();return}if(e.target.closest("[data-asknew]")){if(ASK.busy&&ASK.ctrl)ASK.ctrl.abort();ASK.msgs=[];askPaint();$("askIn").focus();return}
    const p=e.target.closest("[data-askplate]");if(p){const c=caseByPlate(p.dataset.askplate)[0];if(c){if(sel!==null)close();showView("casos");render();open(c.id)}}});
  document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("askp").hidden&&!e.target.closest(".gsearch"))askClose()});
  $("gsAsk").addEventListener("click",()=>askOpen(q.value.trim()||""));
})();



/* ---------- Indicadores a partir dos dossiês (Database) ---------- */
function dossieCases(){
  const pd=s=>{const m=String(s||"").match(/(\d{2})\/(\d{2})\/(\d{4})/);return m?new Date(+m[3],+m[2]-1,+m[1]):null};
  const days=(a,b)=>a&&b?Math.round((b-a)/864e5):null;
  const out=[];
  Object.values(store).forEach(d=>{
    const base=cases.find(c=>c.id===d.id);if(!base)return;
    const v=d.v||{},r=[];const set=(col,val)=>{if(val!=null&&val!==""&&POS[col]!=null)r[POS[col]]=String(val)};
    const alert=pd(v.alerta_ll)||pd(base.date);
    const yn=x=>{x=String(x||"").trim();return !x?"":/^n(ã|a)o\b/i.test(x)?"Não":/^sim\b/i.test(x)?"Sim":""};
    /* tempo de locação, tempo de base */
    set(23,/^\d+$/.test(String(v.tempo_base||"").trim())?String(v.tempo_base).trim():(()=>{const n=days(pd(v.data_retirada),alert);return n!=null&&n>=0?n:""})());
    const dc=days(pd(v.data_cadastro),alert);
    if(dc!=null&&dc>=0)set(22,dc<=15?"1 a 15 dias":dc<=30?"16 a 30 dias":dc<=60?"31 a 60 dias":dc<=90?"61 a 90 dias":dc<=120?"90 a 120 dias":"Acima de 121 dias");
    const pc=pd(v.prim_contrato),uc=pd(v.ult_contrato);if(pc&&uc)set(24,pc.getTime()===uc.getTime()?"Sim":"Não");
    const cr=days(pd(v.data_cadastro),pd(v.data_retirada));if(cr!=null&&cr>=0)set(21,cr>180?"Sim":"Não");
    const ind=String(v.indicada||"").trim();if(ind)set(12,/^n(ã|a)o\b|^-$/i.test(ind)?"Não":"Sim");
    const nb=pd(v.nasc);if(nb&&alert){let a=alert.getFullYear()-nb.getFullYear();if(alert<new Date(alert.getFullYear(),nb.getMonth(),nb.getDate()))a--;
      set(15,a<25?"Inferior à 25":a<=30?"25 à 30":a<=35?"31 à 35":a<=40?"36 à 40":a<=45?"41 à 45":a<=50?"46 à 50":a<=55?"50 à 55":"Superior à 56")}
    set(25,v.plano);
    const deb=String(v.debito||"").replace(/[^\d,.-]/g,"").replace(/\.(?=\d{3}\b)/g,"").replace(",",".");if(deb!==""&&!isNaN(parseFloat(deb)))set(26,parseFloat(deb)>0?"Sim":"Não");
    if(yn(v.bloq)==="Sim")set(32,"Bloqueado por inadimplência");else if(yn(v.negoc)==="Sim")set(32,"Promessa de pagamento");else if(yn(v.bloq)==="Não"||yn(v.negoc)==="Não")set(32,"Não");
    const cb=String(v.chargeback||"").trim();if(cb)set(48,/^sim\b/i.test(cb)?"Sim":/^n(ã|a)o\b/i.test(cb)?"Não":"");
    set(8,String(v.km_dia||"").replace(/[^\d]/g,"")||"");
    const lc=String(v.localizado||"").trim();if(lc)set(59,/^n(ã|a)o/i.test(lc)?"NÃO":/carca/i.test(lc)?"CARCAÇA":/(somente|só).*rastreador/i.test(lc)?"SOMENTE RASTREADOR":"SIM");
    set(34,yn(v.zombie));set(35,yn(v.perdeu));
    const p1=String(v.pern1||"").match(/\d+/);if(p1)set(36,+p1[0]>=50?"Sim":"Não");
    const hm=String(v.alerta_ll||"").match(/(\d{1,2})h/);if(hm)set(87,hm[1]+"h");
    const un=String(v.unidade||"").trim();if(un){set(11,un);const st=un.match(/\(([A-Z]{2})\)/);if(st)set(37,st[1])}
    /* campos sem equivalente no dossiê usam o registro do caso */
    const keep=(col)=>{if(POS[col]!=null&&r[POS[col]]==null&&base.r){const x=g(base.r,col);if(x)r[POS[col]]=x}};
    [11,37].forEach(keep);
    /* multas */
    let nm=0;Object.keys(v).forEach(k=>{if(/^multas\.\d+\.0$/.test(k)&&String(v[k]).trim())nm++});
    /* ocorrência */
    const tp=String(v.tipif||"");let occ=base.occ;if(/furto/i.test(tp))occ="FURTO";else if(/roubo|157/i.test(tp))occ="ROUBO";else if(/apropria|estelion/i.test(tp))occ="FURTO";
    const c=Object.assign({},base,{r,occ,src:"dossie",model:(v.modelo||base.model||"").replace(/_/g," "),multas:nm>0?nm:null});
    if(alert){const yy=String(alert.getFullYear()),mm=String(alert.getMonth()+1).padStart(2,"0"),dd=String(alert.getDate()).padStart(2,"0");c.date=`${dd}/${mm}/${yy}`;c.y=yy;c.sort=yy+mm+dd}
    if(String(v.evento||"").trim())c.alerta=v.evento;
    out.push(c)});
  return out;
}
(function(){
  const _ra=renderAna;renderAna=function(){_ra();
    if(A.src==="dos"){const n=dossieCases().length;$("anaSub").textContent=`Database: ${aCases().length} de ${n} dossiê${n===1?"":"s"} criado${n===1?"":"s"} no app neste filtro`}
    $("aSrc").querySelectorAll("button").forEach(b=>b.classList.toggle("on",b.dataset.s===A.src))};
  $("aSrc").addEventListener("click",e=>{const b=e.target.closest("button");if(!b||b.dataset.s===A.src)return;A.src=b.dataset.s;if(typeof advRefresh==="function")try{advRefresh()}catch(x){}renderAna()});
})();



