var ZONA_T={risk_zone:"zona de risco",investigation:"investigação",stores_yards:"loja/pátio",border:"fronteira"};
(function(){
  const inRing=(x,y,r)=>{let c=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const xi=r[i][0],yi=r[i][1],xj=r[j][0],yj=r[j][1];if(((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))c=!c}return c};
  const inPoly=(x,y,poly)=>{if(!inRing(x,y,poly[0]))return false;for(let k=1;k<poly.length;k++)if(inRing(x,y,poly[k]))return false;return true};
  window.zonaDe=function(lat,lon){if(!isFinite(lat)||!isFinite(lon))return [];const out=[];
    for(const z of ZONAS){const b=z.b;if(lon<b[0]||lon>b[2]||lat<b[1]||lat>b[3])continue;if(z.p.some(p=>inPoly(lon,lat,p)))out.push(z)}
    return out};
  window.zonaTxt=function(lat,lon){const l=window.zonaDe(+lat,+lon).filter(z=>z.ty!=="border");const b=window.zonaDe(+lat,+lon).filter(z=>z.ty==="border");
    const nm=z=>z.ty==="investigation"?"Zona de investigação":`${z.n} (${ZONA_T[z.ty]||z.ty})`;return [...new Set(l.concat(b).map(nm))].join("; ")};
})();



/* ---------- Cópia compartilhada das consultas do Metabase (para quem não tem acesso) ---------- */
var SNAP={pre:null,rec:null,used:false,at:0};
(function(){
  const NOACC=new Set(["server_not_connected","needs_reauth","not_in_manifest","not_granted","consent_required","approval_required","blocked_by_policy","selection_required","capability_disabled","unavailable"]);
  const hs=s=>{let h1=0xdeadbeef,h2=0x41c6ce57;for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);h1=Math.imul(h1^c,2654435761);h2=Math.imul(h2^c,1597334677)}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return (4294967296*(2097151&h2)+(h1>>>0)).toString(36)};
  let D=null,dbP=null;const getDb=()=>dbP||(dbP=(async()=>{try{return window.claude&&window.claude.use?await window.claude.use("db"):null}catch(e){return null}})());
  const _mcp=mcpGet;mcpGet=async function(){const m=await _mcp();return m||(SNAP.pre?{}:null)};
  const hasReal=async()=>!!(await _mcp());
  const _sql=mbSql;mbSql=async function(sql){
    const h=hs(sql);
    if(SNAP.pre&&!(await hasReal())){if(SNAP.pre[h]!==undefined){SNAP.used=true;return SNAP.pre[h]}throw {code:"unavailable"}}
    let r;try{r=await _sql(sql)}catch(e){if(SNAP.pre&&NOACC.has(e&&e.code)&&SNAP.pre[h]!==undefined){SNAP.used=true;return SNAP.pre[h]}throw e}
    if(SNAP.rec)SNAP.rec[h]=r;return r};
  async function load(id){try{const db=await getDb();if(!db)return null;const s=await db.collection("snap").doc(safeId(id)).get();if(!s.exists)return null;const x=s.data();SNAP.at=x.at||0;return JSON.parse(x.data||"null")}catch(e){return null}}
  async function save(id,rec){try{const db=await getDb();if(!db)return;let ents=Object.entries(rec);let str=JSON.stringify(Object.fromEntries(ents));
    if(str.length>700000){ents.sort((a,b)=>JSON.stringify(a[1]).length-JSON.stringify(b[1]).length);while(ents.length&&JSON.stringify(Object.fromEntries(ents)).length>700000)ents.pop();str=JSON.stringify(Object.fromEntries(ents))}
    await db.collection("snap").doc(safeId(id)).set({at:Date.now(),v:MB_VER,data:str})}catch(e){}}
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  async function request(id){try{const db=await getDb();if(db)await db.collection("snapreq").doc(safeId(id)).set({at:Date.now(),by:"app",caso:id})}catch(e){}}
  const watching=new Set();
  async function watch(d){if(watching.has(d.id))return;watching.add(d.id);try{const db=await getDb();if(!db)return;let un=null;
    un=db.collection("snap").doc(safeId(d.id)).onSnapshot(s=>{if(s.exists&&cur&&cur.id===d.id&&!d.v._mb_filled){try{un&&un()}catch(e){}watching.delete(d.id);mbFillDossier(true)}})}catch(e){watching.delete(d.id)}}
  /* coleta as consultas de um caso sem aplicar nada no dossiê */
  async function collect(id){
    const ctx=ctxFor(id),plate=safePlate(ctx.plate),date=isoOf(ctx.date);if(!plate||!date)return null;
    const rec={};const run=async sql=>{const r=await _sql(sql);rec[hs(sql)]=r;return r};
    const q=mbCaseSql(plate,date),kEnd=ktsEnd(ctx,date),kq=ktsSql(plate,date,kEnd);
    const rs=await Promise.allSettled([run(q.perfil),run(q.fin),run(q.listas),run(kq.trilha),run(kq.uso),run(q.docs),run(q.cad),run(q.pag),run(q.ind),run(q.bgc)]);
    const bad=rs.slice(0,3).find(r=>r.status==="rejected");if(bad)throw bad.reason;
    const ini0=String(P0_(rs[0].value).bk_started||"").slice(0,10);
    if(ini0){try{await run(noitesSql(plate,date,ini0))}catch(e){}}
    return rec}
  /* trabalho em segundo plano: quem tem acesso ao Metabase mantém as cópias de todos os dossiês */
  let running=false;
  async function worker(){
    if(running)return;running=true;
    try{const db=await getDb();if(!db||!(await hasReal()))return;
      const have={};try{(await db.collection("snap").get()).docs.forEach(x=>{const v=x.data();have[x.id]={at:v.at||0,v:v.v}})}catch(e){return}
      const raw={};cases.forEach(c=>raw[safeId(c.id)]=c.id);Object.keys(store).forEach(k=>raw[safeId(k)]=k);
      let reqs=[];try{reqs=(await db.collection("snapreq").get()).docs.map(x=>raw[x.id]).filter(Boolean)}catch(e){}
      const DAY=24*3600e3,now=Date.now();
      const todo=[...new Set([...reqs,...Object.keys(store)])].filter(id=>{if(!cases.some(c=>c.id===id))return false;const h=have[safeId(id)],d=store[id];return !h||h.v!==MB_VER||(d&&d.st!=="done"&&now-h.at>DAY)})
        .sort((a,b)=>((have[safeId(a)]&&have[safeId(a)].at)||0)-((have[safeId(b)]&&have[safeId(b)].at)||0)).slice(0,12);
      for(const id of todo){
        while(typeof mbBusy!=="undefined"&&mbBusy)await sleep(2000);
        try{const rec=await collect(id);if(rec&&Object.keys(rec).length>=3){await save(id,rec);if(reqs.includes(id)){try{await db.collection("snapreq").doc(safeId(id)).delete()}catch(e){}}}}
        catch(e){if(NOACC.has(e&&e.code))return}
        await sleep(1500)}
    }finally{running=false}}
  window.snapWorker=worker;
  setTimeout(worker,9000);setInterval(worker,30*60e3);
  const _fill=mbFillDossier;mbFillDossier=async function(auto){
    if(!cur)return _fill(auto);const d=cur;
    SNAP={pre:await load(d.id),rec:{},used:false,at:SNAP.at};
    if(!SNAP.pre&&!(await hasReal())){request(d.id);watch(d);mbBar("mbBar","<b>Sem acesso ao Metabase.</b> Pedimos a atualização automática deste caso: assim que alguém com acesso abrir o app, os dados chegam e o dossiê preenche sozinho.","info");SNAP={pre:null,rec:null,used:false,at:SNAP.at};return}
    try{await _fill(auto)}finally{
      const had=Object.keys(SNAP.rec).length>=3&&d.v._mb_filled&&!SNAP.used;
      if(had)save(d.id,SNAP.rec);
      if(SNAP.used){const t=new Date(SNAP.at).toLocaleString("pt-BR",{timeZone:"America/Sao_Paulo",dateStyle:"short",timeStyle:"short"});d.v._mb_snap_at=t;if(typeof toast==="function")toast("Sem acesso ao Metabase: dados da cópia compartilhada de "+t+".")}
      const keepAt=SNAP.at;SNAP={pre:null,rec:null,used:false,at:keepAt}}};
  /* sem conexão e sem cópia: mensagem clara */
  const MSG0="A consulta ao Metabase só funciona com o app aberto no claude.ai.";
  document.addEventListener("click",e=>{});
})();

/* ---------- Botão "Pedir ao Claude": chama o Claude para atualizar a cópia de um caso ---------- */
(function(){
  const mb=$("edMb");if(!mb)return;
  const b=document.createElement("button");b.className="btn";b.id="edClaude";b.type="button";b.title="Pede ao Claude para consultar o Metabase deste caso e guardar a cópia compartilhada";
  b.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8z"/></svg>Pedir ao Claude';
  mb.insertAdjacentElement("afterend",b);
  b.addEventListener("click",async()=>{
    const d=cur;if(!d)return;const ctx=ctxFor(d.id);
    try{const db=window.claude&&window.claude.use?await window.claude.use("db"):null;if(db)await db.collection("snapreq").doc(safeId(d.id)).set({at:Date.now(),by:"botao",caso:d.id})}catch(e){}
    let c=null,why="";try{c=window.claude&&window.claude.use?await window.claude.use("comments"):null;if(!c)why="comentários indisponíveis nesta visualização"}catch(e){why="comentários: "+((e&&e.code)||e)}
    let st="off";if(c){try{st=await c.canSendToClaude()}catch(e){why="envio ao Claude: "+((e&&e.code)||e)}}
    const txt=`[Atualizar cópia do Metabase] caso=${d.id} placa=${ctx.plate} perda=${ctx.date}\nClaude: rode as consultas do Metabase deste caso e grave a cópia compartilhada (snap/${safeId(d.id)}); o dossiê preenche sozinho para quem não tem acesso.`;
    if(st==="available"){
      b.disabled=true;
      try{const anchor=await c.anchorFor(b);await c.sendToClaude({anchor,text:txt});
        toast("Pedido enviado ao Claude. A cópia chega em alguns minutos e o dossiê preenche sozinho.")}
      catch(e){toast("Não foi possível chamar o Claude ("+((e&&e.code)||e)+"). O pedido ficou registrado para a atualização automática.")}
      finally{b.disabled=false}return}
    if(st==="writers_only"){toast("Só o dono do app pode chamar o Claude. O pedido ficou registrado: quem tem acesso ao Metabase atualiza automaticamente.");return}
    if(!c&&!/^comentários:/.test(why)){toast("Chamar o Claude direto é só para o dono do app. O pedido deste caso ficou registrado: a atualização automática atende assim que alguém com acesso ao Metabase abrir o app, e o dossiê preenche sozinho.");return}
    /* alternativa: abre o comentário do claude.ai com o texto copiado, para enviar ao Claude à mão */
    let copied=false;try{await navigator.clipboard.writeText(txt);copied=true}catch(e){}
    let opened=false;if(c){try{const r=await c.openComposer({element:b});opened=!!(r&&r.opened)}catch(e){}}
    const motivo=why||(st==="no_session"?"nenhuma sessão do Claude está ouvindo agora":"envio direto desligado nesta visualização ("+st+")");
    toast(opened?`Envio direto indisponível (${motivo}). Abri o comentário${copied?": o texto do pedido já está copiado, é só colar e clicar em Enviar ao Claude.":"; descreva o caso e envie ao Claude."}`:`Chamar o Claude não está disponível aqui (${motivo}). O pedido ficou registrado para a atualização automática.${copied?" O texto do pedido foi copiado.":""}`)});
})();



