  $("ddLoss").addEventListener("click",()=>{$("topLoss").click()});
  document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!pane()&&dr.classList.contains("on")&&!document.querySelector("dialog[open]")){ddClose()}});
  /* abrir um dossiê: fica no painel da direita */
