(function(){const st=document.createElement("style");st.textContent='.bd.bd-c{background:var(--surface-2);color:var(--fg-3);border-color:var(--line)}.bd.bd-c.on{background:color-mix(in srgb,var(--bad,#DC2626) 12%,transparent);color:var(--bad-ink,#B91C1C);border-color:color-mix(in srgb,var(--bad,#DC2626) 35%,transparent)}.bd.bd-c svg{margin-right:4px}';document.head.appendChild(st)})();
(function(){
  const cache=new Map();const LI='<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7"/><path d="M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/></svg>',AT='<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M16 8v5a3 3 0 0 0 6 0v-1a10 10 0 1 0-4 8"/></svg>';
  async function calc(d){
    const key=d.id+"|"+(d.updated||0)+"|"+Object.keys(store).length;const c=cache.get(d.id);if(c&&c.key===key)return c.v;
    const ids=new Set();
    for(const [k,val] of Object.entries(d.v||{})){const kind=typeof fieldKind==="function"&&fieldKind(k);if(!kind||!val||typeof val!=="string")continue;
      try{(await findLinks(kind,val,d.id)).forEach(l=>{if(!l.ocr&&l.id!==d.id)ids.add(l.id)})}catch(e){}}
    const men=new Set((d.mentions||[]).map(m=>m.id));try{mentionedBy(d.id).forEach(x=>men.add(x.dos.id))}catch(e){}
    const v={lk:ids.size,mn:men.size};cache.set(d.id,{key,v});return v;
  }
  /* badge de cerca: o local do alerta/perda estava dentro de uma cerca cadastrada? */
  const PIN='<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s7-6.2 7-12a7 7 0 1 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>';
  window.cercaDe=function(d){if(!d||!d.v)return null;let v=String(d.v.alerta_cerca||"").trim(),z="";
    if(/^sim/i.test(v))return {s:1,t:v.replace(/^sim\s*·\s*/i,"")};
    if(/^n[ãa]o/i.test(v))return {s:0,t:""};
    try{const p=typeof parseLL==="function"?parseLL(d.v.alerta_ll):null;if(p&&typeof zonaTxt==="function"){z=zonaTxt(p[0],p[1]);return z?{s:1,t:z}:{s:0,t:""}}}catch(e){}
    return null};
  const cercaHtml=d=>{const c=window.cercaDe(d);if(!c)return "";return c.s?`<span class="bd bd-c on" title="${esc("Dentro de cerca: "+c.t)}">${PIN}Em cerca</span>`:`<span class="bd bd-c" title="Fora das cercas cadastradas">${PIN}Fora de cerca</span>`};
  window.cercaBadge=cercaHtml;
  const html=(v,d)=>cercaHtml(d)+(v.lk?`<span class="bd bd-l" title="Vínculo com outros casos">${LI}Vínculo · ${v.lk}</span>`:"")+(v.mn?`<span class="bd bd-m" title="Menção em texto, em outro caso ou dossiê">${AT}Menção · ${v.mn}</span>`:"");
  const _rl2=renderList;renderList=function(){_rl2();
    document.querySelectorAll("#dlist .dcard").forEach(card=>{const d=store[card.dataset.od];if(!d)return;
      const row=document.createElement("span");row.className="dbadges";card.insertBefore(row,card.querySelector(".prog"));
      const c=cache.get(d.id);if(c)row.innerHTML=html(c.v,d);
      calc(d).then(v=>{if(row.isConnected)row.innerHTML=html(v,d)})})};
})();
