        const back=()=>{const mm=$("edMain");if(mm)mm.scrollTo({top:st,behavior:"instant"});if(fid){const el=$(fid);if(el&&document.activeElement!==el){try{el.focus({preventScroll:true});if(s0!=null&&el.setSelectionRange)el.setSelectionRange(s0,s1)}catch(e){}}}};
