/* ---------- Gráficos dinâmicos: clicar em uma barra/fatia filtra todos os outros ---------- */
(function(){
  if(typeof renderAna!=="function"||typeof aCases!=="function"||typeof countBy!=="function")return;
  const XF={},REG={};
  const aBase=aCases;
  const xfOk=(c,except)=>{for(const id in XF){if(id===except)continue;const f=XF[id];if(!f.v.size||!f.test)continue;let ok=false;for(const v of f.v){if(f.test(c,v)){ok=true;break}}if(!ok)return false}return true};
  const xfList=ex=>aBase().filter(c=>xfOk(c,ex));
  window.aCases=function(){return aBase().filter(c=>xfOk(c))};
  const active=id=>XF[id]&&XF[id].v.size>0;
  /* marca os resultados de countBy com a função que gerou o valor */
  const _cb=countBy;window.countBy=function(list,fn,opts){const r=_cb(list,fn,opts);r.fn=fn;r.opts=opts;return r};
  const rowsWrap=(name,mk)=>{const o=window[name];window[name]=function(title,res,x){
    if(res&&res.fn&&active(title))res=_cb(xfList(title),res.fn,res.opts);
    const h=o.call(this,title,res,x);if(res&&res.fn)REG[title]={kind:name,fn:res.fn,rows:res.rows,test:(c,v)=>res.fn(c)===v,lab:v=>String(v)};return h}};
  rowsWrap("hbars");rowsWrap("splitBar");
  const _rb=rateBars;window.rateBars=function(title,list,fn,opts){if(active(title))list=xfList(title);const h=_rb.call(this,title,list,fn,opts);REG[title]={kind:"rate",fn,test:(c,v)=>fn(c)===v,lab:v=>String(v)};return h};
  const _mo=monthly;window.monthly=function(list){const id="Perdas por mês";if(active(id))list=xfList(id);
    const keys=[...new Set(list.map(c=>c.sort.slice(0,6)))].filter(k=>k.length===6).sort();REG[id]={kind:"month",keys,list,test:(c,v)=>c.sort.slice(0,6)===v,lab:v=>(typeof MES!=="undefined"?MES[+v.slice(4)-1]:v.slice(4))+"/"+v.slice(2,4)};return _mo.call(this,list)};
  const _ho=hours;window.hours=function(title,list,col,sub){if(active(title))list=xfList(title);REG[title]={kind:"hour",test:(c,v)=>{const h=NORM.hora(g(c.r,col));return h!=null&&h%24===v},lab:v=>String(v).padStart(2,"0")+"h"};return _ho.call(this,title,list,col,sub)};
  /* barra de filtros ativos */
  const view=$("anaView");let bar=$("xfBar");
  if(!bar&&view){bar=document.createElement("div");bar.id="xfBar";bar.hidden=true;const body=$("anaBody");body.parentNode.insertBefore(bar,body)}
  const st=document.createElement("style");st.textContent=`
  #xfBar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 12px;padding:8px 12px;border-radius:12px;background:var(--accent-soft);font-size:12.5px;animation:aFadeUp .25s var(--ease-out) both}
  #xfBar[hidden]{display:none}#xfBar b{font-weight:700}
  #xfBar .xc{display:inline-flex;align-items:center;gap:6px;padding:3px 6px 3px 10px;border-radius:999px;background:var(--surface);border:1px solid color-mix(in srgb,var(--accent) 35%,transparent)}
  #xfBar .xc button{border:0;background:transparent;cursor:pointer;color:var(--fg-3);width:18px;height:18px;border-radius:50%;line-height:1;padding:0}#xfBar .xc button:hover{background:var(--bg);color:var(--fg)}
  #xfBar .xclr{margin-left:auto;border:0;background:transparent;color:var(--accent-ink-2,var(--accent));font-weight:600;cursor:pointer}
  .xf-item{cursor:pointer;transition:opacity .2s,background-color .2s,box-shadow .2s,outline-color .2s}
  .hb-r.xf-item:hover{background:var(--bg);border-radius:8px}
  .xf-off{opacity:.38}.xf-on{opacity:1}
  .hb-r.xf-on{background:var(--accent-soft);border-radius:8px}.hb-r.xf-on .l{font-weight:700}
  .m-slot.xf-on .m-bar{box-shadow:0 0 0 2px var(--accent);border-radius:4px}.cols .c.xf-on i{box-shadow:0 0 0 2px var(--accent)}
  .split i.xf-on{box-shadow:inset 0 0 0 2px var(--accent)}.legend span.xf-on{font-weight:700;color:var(--accent-ink-2,var(--accent))}.legend span.xf-item:hover{opacity:1;text-decoration:underline}
  .xf-ren .home *{animation:none!important}
  .m-bar i[data-xfo]{cursor:pointer;transition:filter .15s}.m-bar i[data-xfo]:hover{filter:brightness(1.12)}`;document.head.appendChild(st);
  const labelOf=id=>{const f=XF[id];return `${id}: ${[...f.v].map(v=>f.lab?f.lab(v):v).join(", ")}`};
  function paintBar(){const ids=Object.keys(XF).filter(active);if(!bar)return;bar.hidden=!ids.length;if(!ids.length){bar.innerHTML="";return}
    bar.innerHTML=`<b>Filtrando os gráficos:</b>${ids.map(id=>`<span class="xc">${esc(labelOf(id))}<button type="button" data-xfx="${esc(id)}" aria-label="Remover filtro">✕</button></span>`).join("")}<button type="button" class="xclr" data-xfclr="1">Limpar tudo</button>`}
  /* após cada desenho, marca os itens clicáveis e o estado de cada gráfico */
  const _ra=renderAna;
  window.renderAna=function(){const home=document.querySelector(".home"),st0=home?home.scrollTop:0,pg=window.scrollY;
    const r=_ra.apply(this,arguments);
    try{decorate()}catch(e){}paintBar();
    if(home)home.scrollTo({top:st0,behavior:"instant"});
    return r};
  function decorate(){document.querySelectorAll("#anaBody .ccard").forEach(card=>{const h=card.querySelector("h3");if(!h)return;const id=h.textContent.trim();const R=REG[id];if(!R)return;
      const f=XF[id],on=f&&f.v.size?f.v:null;const mark=(el,v)=>{if(!el)return;el.classList.add("xf-item");el.dataset.xf=id;el.dataset.xfi=String(typeof v==="number"?"n:"+v:"s:"+v);if(on){const sel=on.has(v);el.classList.toggle("xf-on",sel);el.classList.toggle("xf-off",!sel)}};
      if(R.kind==="hbars"){card.querySelectorAll(".hb-r").forEach((el,i)=>{const row=R.rows[i];if(row&&row[0]!=="Outros")mark(el,row[0])})}
      else if(R.kind==="splitBar"){card.querySelectorAll(".split i").forEach((el,i)=>{const row=R.rows[i];if(row)mark(el,row[0])});card.querySelectorAll(".legend span").forEach((el,i)=>{const row=R.rows[i];if(row)mark(el,row[0])})}
      else if(R.kind==="rate"){card.querySelectorAll(".hb-r").forEach(el=>{const l=el.querySelector(".l");if(l)mark(el,l.textContent)})}
      else if(R.kind==="month"){card.querySelectorAll(".m-slot").forEach((el,i)=>{const k=R.keys[i];if(!k)return;mark(el,k);
        /* cada faixa colorida da barra = tipo de ocorrência daquele mês (de cima para baixo, ordem invertida) */
        const present=Object.keys(OCC).filter(o=>R.list.some(c=>c.sort.startsWith(k)&&c.occ===o)).reverse();
        el.querySelectorAll(".m-bar i").forEach((sg,j)=>{if(present[j]){sg.dataset.xfo=OCC[present[j]][0];sg.title="Filtrar "+OCC[present[j]][0]+" neste mês"}})})}
      else if(R.kind==="hour"){card.querySelectorAll(".cols .c").forEach((el,i)=>mark(el,i))}})}
  const render=()=>{document.body.classList.add("xf-ren");const first=Object.keys(XF).some(active);if(!first)setTimeout(()=>document.body.classList.remove("xf-ren"),700);renderAna()};
  const parse=s=>s.startsWith("n:")?+s.slice(2):s.slice(2);
  document.addEventListener("click",e=>{
    const x=e.target.closest("[data-xfx]");if(x){const f=XF[x.dataset.xfx];if(f)f.v.clear();render();return}
    if(e.target.closest("[data-xfclr]")){Object.values(XF).forEach(f=>f.v.clear());render();return}
    const sg=e.target.closest("#anaBody .m-bar i[data-xfo]");
    if(sg){const slot=sg.closest(".m-slot"),Rm=REG["Perdas por mês"],Ro=REG["Tipo de ocorrência"];if(slot&&Rm&&Ro){const key=parse(slot.dataset.xfi),lab=sg.dataset.xfo;
        const M=XF["Perdas por mês"]||(XF["Perdas por mês"]={v:new Set()}),O=XF["Tipo de ocorrência"]||(XF["Tipo de ocorrência"]={v:new Set()});
        const same=M.v.size===1&&M.v.has(key)&&O.v.size===1&&O.v.has(lab);M.v.clear();O.v.clear();if(!same){M.v.add(key);O.v.add(lab)}
        M.test=Rm.test;M.lab=Rm.lab;O.test=Ro.test;O.lab=Ro.lab;render();return}}
    const it=e.target.closest("#anaBody .xf-item");if(!it)return;const id=it.dataset.xf,R=REG[id];if(!R)return;const v=parse(it.dataset.xfi);
    const f=XF[id]||(XF[id]={v:new Set()});f.test=R.test;f.lab=R.lab;f.v.has(v)?f.v.delete(v):f.v.add(v);render()});
  document.addEventListener("keydown",e=>{if(e.key==="Escape"&&Object.values(XF).some(f=>f.v.size)&&!document.querySelector("dialog[open]")&&!e.target.closest("input,textarea,select")){Object.values(XF).forEach(f=>f.v.clear());render()}});
  /* limpa ao trocar de origem dos dados (Planilha/Database) */
  window.xfClear=()=>{Object.values(XF).forEach(f=>f.v.clear());paintBar()};
  try{renderAna()}catch(e){}
})();



/* ---------- Aba de insights com cara de dashboard do Metabase ---------- */
