  async function dbPut(db,name,a,at){const col=db.collection("modelo");let j=pack(a);const P=[];for(let i=0;i<j.length;i+=CH)P.push(j.slice(i,i+CH));if(!P.length)P.push("[]");
    for(let i=P.length-1;i>=1;i--)await col.doc(name+"_"+i).set({at,j:P[i]});
    await col.doc(name).set({at,n:a.length,np:P.length,j:P[0]})}
