    MM.ov=BM.map(([k,u,b,minZ])=>{const layer=L.imageOverlay(u,[[b[0],b[1]],[b[2],b[3]]],{className:"rm-base",interactive:false,zIndex:minZ===0?1:minZ<11?2:3});
      layer.on("error",()=>{try{MM.map.removeLayer(layer)}catch(e){}});return {minZ,b:L.latLngBounds([b[0],b[1]],[b[2],b[3]]),layer}});
    const sync=()=>{const z=MM.map.getZoom(),vb=MM.map.getBounds();MM.ov.forEach(o=>{const want=z>=o.minZ&&vb.intersects(o.b),has=MM.map.hasLayer(o.layer);if(want&&!has)o.layer.addTo(MM.map);else if(!want&&has)MM.map.removeLayer(o.layer)})};
