      /* o gerador lê o dossiê aberto no editor: abre por baixo do modal */
      if(typeof cur==="undefined"||!cur||cur.id!==id){if(over){const sv=window.showView,navOn=[...document.querySelectorAll("[id^=nav-].on")];window.showView=()=>{};try{openDossier(id)}finally{window.showView=sv}document.querySelectorAll("[id^=nav-]").forEach(n=>n.classList.toggle("on",navOn.includes(n)));$("dosEd").hidden=true;document.body.classList.remove("editing")}else{openDossier(id);P.opened=true}}
      for(let i=0;i<40&&!(typeof cur!=="undefined"&&cur&&cur.id===id&&(over||document.querySelector("#edForm [data-k]")));i++)await new Promise(r=>setTimeout(r,100));
