    const sets={};const A=(k,o)=>{const q=k+"|"+o;return sets[q]||(sets[q]={p:new Set(),r:new Set(),x:new Set()})};
    (a&&a.values||[]).forEach(r=>{const tipo=String(r[2]||"").trim().toLowerCase(),ci=dmy(r[4]),rc=dmy(r[13]),o=OCC(r[5]),pl=String(r[3]||"").trim().toUpperCase()||("_"+Math.random());
      if(ci&&tipo.startsWith("poss"))A(mk(ci.y,ci.m),o).x.add(pl);else{if(ci)A(mk(ci.y,ci.m),o).p.add(pl);if(rc)A(mk(rc.y,rc.m),o).r.add(pl)}});
