    M.forEach((x,i)=>{s+=slot(i,pw,l,t,ph,x,y);const cx=X(i),over=x.lim!=null&&x.net>x.lim,h=Math.max(0,x.net)/ymax*ph;s+=bar(cx-bw/2,Y(Math.max(0,x.net)),bw,h,6,2,over?"url(#lp)":"url(#ly)",dim(x.m))+`<text class="v" x="${cx}" y="${Y(Math.max(0,x.net))-6}" text-anchor="middle" pointer-events="none"${dim(x.m)}>${x.net}</text><text x="${cx}" y="${H-b+17}" text-anchor="middle" pointer-events="none" style="${S.mon===x.m?"font-weight:900;fill:var(--mb-brand)":""}">${MES[i]}</text>`});
