    let s=`<svg width="240" height="158" viewBox="0 0 240 158" role="img" aria-label="Car loss do período">${seg(0,.4,"#6B9F3B")}${seg(.4,.7,"#F3BE2B")}${seg(.7,1,"#E9625E")}`;
    [0,.5,1].forEach(f=>{const [x,y]=P(f,R+10);s+=`<text x="${x}" y="${y+(f===.5?-2:12)}" text-anchor="middle" style="font-size:10px">${nf(f*MAX,2)}</text>`});
    if(v!=null){const f=Math.min(1,Math.max(0,v/MAX)),[nx,ny]=P(f,R-w-6);s+=`<line x1="${cx}" y1="${cy}" x2="${nx}" y2="${ny}" stroke="var(--mb-dark)" stroke-width="3.5" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="7" fill="var(--mb-dark)"/><circle cx="${cx}" cy="${cy}" r="2.5" fill="var(--mb-card)"/>`}
