  const IC={net:'<path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/>',p:'<path d="M12 3 4 6v6c0 4.4 3.4 8.3 8 9 4.6-.7 8-4.6 8-9V6z"/><path d="M12 8v5M12 16h.01"/>',r:'<path d="M12 3 4 6v6c0 4.4 3.4 8.3 8 9 4.6-.7 8-4.6 8-9V6z"/><path d="M9 12l2 2 4-4"/>',x:'<circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/>',bar:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',gau:'<path d="M4 17a8 8 0 1 1 16 0"/><path d="M12 17l4-5"/>',lim:'<path d="M3 12h18"/><path d="M6 8v8M18 8v8"/>',yoy:'<path d="M3 17c3-8 5 2 9-4s6-3 9-6"/>'};
