  panel.addEventListener("mousemove",e=>{const t=e.target.closest("[data-tip]");if(!t){tip.style.display="none";return}tip.innerHTML=t.dataset.tip;tip.style.display="block";const w=tip.offsetWidth,x=Math.min(innerWidth-w-8,e.clientX+14);tip.style.left=x+"px";tip.style.top=Math.max(8,e.clientY-tip.offsetHeight-10)+"px"});
