  const on=v=>{ana.classList.toggle("mg-on",v);document.body.classList.toggle("mg-on",v);btn.classList.toggle("on",v);if(v){tabs.querySelectorAll("button[data-t]").forEach(b=>b.classList.remove("on"));if(!S.loaded&&!S.busy)load(false);else paint()}};
  const place=()=>{if(!tabs.contains(btn))tabs.insertBefore(btn,tabs.firstChild);if(ana.classList.contains("mg-on")){btn.classList.add("on");tabs.querySelectorAll("button[data-t]").forEach(b=>b.classList.remove("on"))}};
