  const setTab=t=>{B.classList.toggle("tab-dos",t==="dos");B.classList.toggle("tab-docs",t==="docs");B.classList.toggle("tab-mon",t==="mon");B.classList.toggle("tab-map",t==="map");B.classList.toggle("tab-home",t==="home");
    Object.entries(TABS).forEach(([id,x])=>{const el=$(id);if(el)el.classList.toggle("on",x===t)});if(t==="dos")setTimeout(render,0)};
  setTab("home");
  Object.entries(TABS).forEach(([id,t])=>{const el=$(id);if(el)el.addEventListener("click",()=>setTab(t),true)});
  const logo=document.querySelector(".rail .logo");if(logo)logo.addEventListener("click",()=>setTab("home"),true);
  const _od=openDossier;openDossier=function(){setTab("dos");return _od.apply(this,arguments)};
  const _dd=ddOpen;ddOpen=function(){setTab("dos");return _dd.apply(this,arguments)};
