  document.addEventListener("click",e=>{if(pop&&!e.target.closest(".drv-pop")&&!e.target.closest("[data-pop]"))closePop()},true);document.addEventListener("keydown",e=>{if(e.key==="Escape")closePop()});
  function menu(anchor,items){closePop();const m=document.createElement("div");m.className="drv-pop";m.innerHTML=items.map((it,i)=>it==="-"?"<hr>":`<button type="button" data-i="${i}" class="${it.sel?"sel":""}${it.dg?" dg":""}">${it.t}</button>`).join("");document.body.appendChild(m);
    const r=anchor.getBoundingClientRect();m.style.left=Math.min(r.left,innerWidth-m.offsetWidth-12)+"px";m.style.top=Math.min(r.bottom+6,innerHeight-m.offsetHeight-12)+"px";pop=m;
    m.addEventListener("click",e=>{const b=e.target.closest("button[data-i]");if(!b)return;const it=items[+b.dataset.i];if(it.dg&&!b.classList.contains("armed")){b.classList.add("armed");b.textContent="Confirmar exclusão";return}closePop();it.fn&&it.fn()})}
