  const tagHtml=x=>`<span class="tg ${x.st==="none"?"":x.st}">${x.st==="done"?"Concluído":x.st==="draft"?"Em andamento":"Não iniciado"}</span>`+(x.cerca===true?`<span class="tg cerca">Em cerca</span>`:"")+(x.lk?`<span class="tg lnk">Vínculo</span>`:"")+(x.rv==="pending"?`<span class="tg rvp" title="${e2(x.rqn?"Pedida por "+x.rqn:"")}">Pendente revisão</span>`:x.rv==="returned"?`<span class="tg rvr">Devolvido</span>`:x.rv==="ok"?`<span class="tg rvo">Revisado</span>`:"");
