  const cardHtml=x=>`<div class="dr-card${S.sel.has(x.id)?" sel":""}" role="button" tabindex="0" data-id="${e2(x.id)}" data-k="${x.k}"><div class="th">${x.k==="d"?`<label class="rs"><input type="checkbox" data-sel="${e2(x.id)}"${S.sel.has(x.id)?" checked":""} aria-label="Selecionar"></label>`:""}<b>${e2(x.plate)}</b><div class="tags">${tagHtml(x)}${pcHtml(x)}</div></div><div class="ft"><span class="ico ${x.st}" style="display:grid;place-items:center;border-radius:5px;color:#fff;flex:none">${I.doc.replace("<svg","<svg style=\"width:11px;height:11px;stroke:#fff;fill:none;stroke-width:2.4\"")}</span><div><b>${e2(x.num||x.model||x.plate)}</b><small>${e2(modTxt(x))}</small></div></div></div>`;
