    catch(er){C.busy=false;cPaint();if(!quiet)toast(er&&er.code==="server_not_connected"?"Conecte o Claude Code Remote em claude.ai → Configurações → Conectores.":"Os CNPJs entraram na fila, mas não consegui iniciar a consulta agora.");return}
