  const navMnt=document.getElementById("nav-mnt"),nbg=document.createElement("button");nbg.id="nav-gr";nbg.type="button";
  nbg.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="6" r="2.5"/><circle cx="18" cy="8" r="2.5"/><circle cx="12" cy="18" r="2.5"/><path d="M8.3 7l7.4.6M7.4 8.2l3.4 7.6M16.9 10.2l-3.7 6"/></svg>Graph';
