      for(let i=np-1;i>=0;i--)await db.collection("modelo").doc(i?"mir_pf_"+i:"mir_pf").set(i?{at:now,j:j.slice(i*MCH,(i+1)*MCH)}:{at:now,np,n:Object.keys(m).length,sync:now,j:j.slice(0,MCH)});
