      const ids=[],hold=new Set();G.N.forEach(n=>{if(n.t==="p")(n.dids||[]).forEach(d=>{d=sq(d);if(d&&!ids.includes(d))ids.push(d);if(d&&(n.plates||[]).length)hold.add(d)})});
      const need=ids.filter(d=>!m[d]||Date.now()-(m[d].at||0)>12*36e5).sort((a,b)=>((hold.has(b)?1:0)-(hold.has(a)?1:0))||(((m[a]&&m[a].at)||0)-((m[b]&&m[b].at)||0))).slice(0,240);
