    const pick=()=>[...G.N.values()].filter(n=>(n.t==="c"&&n.label.replace(/[^A-Z0-9]/g,"")===pq)||(n.t==="p"&&(n.plates||[]).some(p=>p.plate.replace(/[^A-Z0-9]/g,"")===pq))||(n.t==="p"&&((nq.length>=4&&n.label.includes(nq))||(isCpf&&docMatch(n.doc,dq))))||(n.t==="e"&&((dq.length===14&&n.cnpj===dq)||(nq.length>=4&&normN(n.label).includes(nq))))).map(n=>n.id);
