      dlg.addEventListener("drop",e=>{e.preventDefault();const f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];if(f&&/^(image\/|application\/pdf)/.test(f.type)){FILE=f;ST.rows=[];ST.msg="";paint()}});
