  /* ---------- busca no treble_dlt ---------- */
  const lit=s=>String(s).replace(/[^0-9]/g,"");
  function searchSql(P){const ks=[],cps=[];P.forEach(p=>{p.tels.forEach(t=>{const v=`('${t.ddd}','${t.l8}')`;if(!ks.includes(v))ks.push(v)});if(p.cpf&&!cps.includes(p.cpf))cps.push(p.cpf)});
    return `WITH ks(ddd, l8) AS (VALUES ${ks.length?ks.join(", "):"('00','00000000')"}),
cp(c) AS (VALUES ${cps.length?cps.map(c=>`('${lit(c)}')`).join(", "):"('00000000000')"}),
s0 AS (SELECT session_id, cellphone, CASE WHEN length(cellphone) >= 12 AND substr(cellphone, 1, 2) = '55' THEN substr(cellphone, 3, 2) ELSE substr(cellphone, 1, 2) END ddd FROM treble_dlt.fact_treble_sessions WHERE substr(cellphone, -8) IN (SELECT l8 FROM ks)),
sp AS (SELECT session_id, 'tel' m, ddd || substr(cellphone, -8) k FROM s0 WHERE ddd || substr(cellphone, -8) IN (SELECT ddd || l8 FROM ks)),
sc AS (SELECT session_id, 'cpf' m, variable_value k FROM treble_dlt.fact_treble_session_variables WHERE variable_name IN ('driver_cpf', 'hubspot_treble_cpf_retorno') AND variable_value IN (SELECT c FROM cp)),
ac AS (SELECT session_id, 'tel' m, substr(contact_wa_id, 3, 2) || substr(contact_wa_id, -8) k FROM treble_dlt.fact_agent_conversations WHERE session_id IS NOT NULL AND substr(contact_wa_id, -8) IN (SELECT l8 FROM ks) AND substr(contact_wa_id, 3, 2) || substr(contact_wa_id, -8) IN (SELECT ddd || l8 FROM ks)),
hit AS (SELECT session_id, m, k FROM sp UNION ALL SELECT session_id, m, k FROM sc UNION ALL SELECT session_id, m, k FROM ac),
hs AS (SELECT session_id, array_join(array_agg(DISTINCT m || ':' || k), ',') hits FROM hit GROUP BY session_id),
se AS (SELECT * FROM (SELECT *, row_number() OVER (PARTITION BY session_id ORDER BY synced_at DESC) rn FROM treble_dlt.fact_treble_sessions WHERE session_id IN (SELECT session_id FROM hs)) WHERE rn = 1),
sm AS (SELECT session_id, count(DISTINCT message_id) nm, count(DISTINCT CASE WHEN sender = 'USER' THEN message_id END) nu, format_datetime(min(created_at) AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss') t1, format_datetime(max(created_at) AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss') t2 FROM treble_dlt.fact_treble_session_messages WHERE session_id IN (SELECT session_id FROM hs) GROUP BY session_id),
am AS (SELECT session_id, count(DISTINCT message_id) na FROM treble_dlt.fact_agent_conversation_messages WHERE session_id IN (SELECT session_id FROM hs) GROUP BY session_id),
ag AS (SELECT session_id, max_by(agent_name, created_at) agent, max_by(team_name, created_at) team, max_by(tag_name, created_at) tag, max_by(status, created_at) cst, max(rating) rating, min(agent_conversation_id) acid FROM treble_dlt.fact_agent_conversations WHERE session_id IN (SELECT session_id FROM hs) GROUP BY session_id)
SELECT hs.hits, CAST(se.session_id AS varchar) sid, se.cellphone, format_datetime(se.created_at AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss') cr, format_datetime(se.finished_at AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss') fi, se.status, se.direction, se.poll_name, coalesce(sm.nm, 0) nm, coalesce(sm.nu, 0) nu, coalesce(am.na, 0) na, sm.t1, sm.t2, ag.agent, ag.team, ag.tag, ag.cst, ag.rating, ag.acid FROM hs JOIN se ON se.session_id = hs.session_id LEFT JOIN sm ON sm.session_id = hs.session_id LEFT JOIN am ON am.session_id = hs.session_id LEFT JOIN ag ON ag.session_id = hs.session_id ORDER BY se.created_at`}
  const near=(p,L)=>L.sort((a,b)=>Math.abs(days(a.cr,p.d))-Math.abs(days(b.cr,p.d))||b.cr.localeCompare(a.cr));
  function groupDup(L){const m=new Map();L.forEach(x=>{const k=[x.cr.slice(0,16),x.poll,x.phone,x.nm,x.na,x.agent].join('|'),g=m.get(k);if(g){g.dup=(g.dup||1)+1;g.sids.push(x.sid);x.via.forEach(v=>{if(!g.via.includes(v))g.via.push(v)})}else{x.sids=[x.sid];m.set(k,x)}});return [...m.values()]}
  function matchRows(P,rows){P.forEach(p=>{p.res=[];p.at=Date.now()});
    rows.forEach(r=>{const hits=String(r.hits||"").split(",").filter(Boolean).map(h=>{const i=h.indexOf(":");return [h.slice(0,i),h.slice(i+1)]});
      P.forEach(p=>{const via=[];hits.forEach(([m,k])=>{if(m==="cpf"&&p.cpf&&k===p.cpf&&!via.includes("CPF"))via.push("CPF");if(m==="tel"){const t=p.tels.find(t=>t.ddd+t.l8===k);if(t&&!via.includes("Telefone"+(t.tag==="emergência"?" de emergência":"")))via.push("Telefone"+(t.tag==="emergência"?" de emergência":""))}});
        if(via.length&&!p.res.some(z=>z.sid===String(r.sid)))p.res.push({sid:String(r.sid),cr:r.cr,fi:r.fi||"",phone:dig(r.cellphone),st:r.status||"",dir:r.direction||"",poll:r.poll_name||"",nm:+r.nm||0,nu:+r.nu||0,na:+r.na||0,t1:r.t1||"",t2:r.t2||"",agent:r.agent||"",team:r.team||"",tag:r.tag||"",cst:r.cst||"",rating:r.rating==null?"":r.rating,acid:r.acid||"",via})})});P.forEach(p=>{p.res=near(p,groupDup(p.res))})}
  /* ---------- cache compartilhado (quem não tem Metabase lê daqui) ---------- */
  async function idxLoad(){const out={};try{const db=await dbg();if(!db)return out;const s=await db.collection("modelo").doc("conv_idx").get();if(!s.exists)return out;const d=s.data();let j=d.j||"";for(let i=1;i<(d.np||1);i++){const p=await db.collection("modelo").doc("conv_idx_"+i).get();if(!p.exists)return out;j+=p.data().j||""}Object.assign(out,JSON.parse(j||"{}"))}catch(e){}return out}
  async function idxSave(){try{const db=await dbg();if(!db)return;const o={};C.rows.forEach(r=>{if(r.res)o[r.k]={at:r.at,v:r.res,ver:2}});let j=JSON.stringify(o);while(j.length>CH*6){const ks=Object.keys(o).sort((a,b)=>o[a].at-o[b].at);delete o[ks[0]];j=JSON.stringify(o)}
      const np=Math.max(1,Math.ceil(j.length/CH));for(let i=np-1;i>=0;i--)await db.collection("modelo").doc(i?"conv_idx_"+i:"conv_idx").set(i?{at:Date.now(),j:j.slice(i*CH,(i+1)*CH)}:{at:Date.now(),np,j:j.slice(0,CH)})}catch(e){}}
  async function runSearch(force){if(C.busy)return;if(!await mbOk()){C.msg="Sem acesso ao Metabase: mostrando as conversas já salvas.";paint();return}
    const stale=r=>force||!r.res||Date.now()-r.at>12*36e5;const todo=C.rows.filter(r=>(r.cpf||r.tels.length)&&stale(r));
    if(!todo.length){C.msg="Tudo em dia.";paint();return}
    C.busy=1;const run=++C.run,B=[];for(let i=0;i<todo.length;i+=25)B.push(todo.slice(i,i+25));let done=0,fail=0,k=0;C.prog=0;paint();
    const work=async()=>{while(k<B.length&&run===C.run){const b=B[k++];try{const r=await mbSql(searchSql(b));matchRows(b,r)}catch(e){fail++}done+=b.length;C.prog=done/todo.length;C.msg=`Buscando… ${Math.min(done,todo.length)} de ${todo.length} perdas`;paintSide()}};
    await Promise.all([work(),work()]);C.busy=0;C.prog=null;C.msg=fail?`Busca concluída com ${fail} lote(s) com falha. Clique de novo para completar.`:"Busca concluída.";await idxSave();paint()}
  /* ---------- conversa ---------- */
  function threadSql(sid){sid=lit(sid);return `WITH s0 AS (SELECT coalesce(max(root_session_id), ${sid}) r FROM treble_dlt.fact_treble_sessions WHERE session_id = ${sid}),
ss AS (SELECT DISTINCT session_id FROM treble_dlt.fact_treble_sessions WHERE root_session_id = (SELECT r FROM s0) OR session_id = (SELECT r FROM s0) OR session_id = ${sid}),
ac AS (SELECT DISTINCT agent_conversation_id FROM treble_dlt.fact_agent_conversations WHERE session_id IN (SELECT session_id FROM ss))
SELECT 's' src, CAST(message_id AS bigint) mid, format_datetime(created_at AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss') ts, sender, type, text, file_url, filename, hsm_name, delivered_at IS NOT NULL dl, read_at IS NOT NULL rd, error, CAST(NULL AS varchar) agent FROM (SELECT *, row_number() OVER (PARTITION BY message_id ORDER BY synced_at DESC) rn FROM treble_dlt.fact_treble_session_messages WHERE session_id IN (SELECT session_id FROM ss)) WHERE rn = 1
UNION ALL SELECT 'a', CAST(message_id AS bigint), format_datetime(created_at AT TIME ZONE 'America/Sao_Paulo', 'yyyy-MM-dd HH:mm:ss'), sender, category, content, CAST(NULL AS varchar), CAST(NULL AS varchar), CAST(NULL AS varchar), delivered_at IS NOT NULL, read_at IS NOT NULL, CAST(NULL AS varchar), agent_name FROM (SELECT *, row_number() OVER (PARTITION BY message_id ORDER BY synced_at DESC) rn FROM treble_dlt.fact_agent_conversation_messages WHERE session_id IN (SELECT session_id FROM ss) OR agent_conversation_id IN (SELECT agent_conversation_id FROM ac)) WHERE rn = 1
ORDER BY 3, 1 LIMIT 2500`}
  const nt=s=>String(s||"").toLowerCase().replace(/\s+/g," ").trim();
  function mergeMsgs(rows){const a=rows.filter(r=>r.src==="a"),s=rows.filter(r=>r.src==="s"),t=x=>Date.parse(String(x.ts).replace(" ","T")+"Z"),bd=x=>nt(plain(x.text)),ty=x=>String(x.type||"").toLowerCase().replace(/^hsm$/,"hsm");
    const keep=s.filter(x=>!a.some(y=>{const dt=Math.abs(t(x)-t(y)),bx=bd(x),by=bd(y);return bx&&by?(bx===by&&dt<=120e3):(!bx&&!by&&ty(x)===ty(y)&&dt<=30e3)}));return a.concat(keep).sort((x,y)=>String(x.ts).localeCompare(String(y.ts))||(x.src<y.src?1:-1))}
  async function thrLoad(sid){if(C.thr.has(sid))return C.thr.get(sid);let msgs=null,from="";
    if(await mbOk()){try{const r=await mbSql(threadSql(sid));msgs=mergeMsgs(r).map(m=>[m.ts,m.sender||"",m.type||"",String(m.text||"").slice(0,1500),m.file_url||"",m.hsm_name||"",m.dl?1:0,m.rd?1:0,m.error||"",m.agent||""]);from="live";
        try{const db=await dbg();if(db)await db.collection("modelo").doc("conv_t2_"+lit(sid)).set({at:Date.now(),j:JSON.stringify(msgs.slice(0,1200))})}catch(e){}}catch(e){msgs=null}}
    if(!msgs){try{const db=await dbg();if(db){const s=await db.collection("modelo").doc("conv_t2_"+lit(sid)).get();if(s.exists){msgs=JSON.parse(s.data().j||"[]");from="saved";C.thrAt=s.data().at}}}catch(e){}}
    const o={msgs:msgs,from};C.thr.set(sid,o);return o}
  /* ---------- ligação telefone → perda ---------- */
  function pidx(){if(C.pidx)return C.pidx;const m=new Map();C.rows.forEach(r=>r.tels.forEach(t=>{const k=t.ddd+t.l8;if(!m.has(k))m.set(k,[]);if(!m.get(k).includes(r))m.get(k).push(r)}));C.pidx=m;return m}
  const linksOf=phone=>{const k=phoneKeys(phone);return k?(pidx().get(k.ddd+k.l8)||[]):[]};
  const lkHtml=phone=>{const L=linksOf(phone);if(!L.length)return"";return L.slice(0,2).map(r=>`<button type="button" class="cv-lk" data-g="${E(r.k)}" title="Abrir a perda ${E(r.plate)}">Perda ${E(r.plate)}</button>`).join(" ")+(L.length>2?` <span class="cv-m">+${L.length-2}</span>`:"")};
  const nz=s=>String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"").toLowerCase();
