      let o={w:K.w,only:K.only,h:K.hits.map(h=>[h.sid,h.label,h.ts,h.snd,h.tx,h.phone])},j=JSON.stringify(o);while(j.length>SIZE&&o.h.length>20){o.h=o.h.slice(0,Math.floor(o.h.length*.85));j=JSON.stringify(o)}
