    C.ci.hits.forEach(h=>{const t=tgBy(h.tk);if(!t)return;if(C.ci.other&&sameTel(t,h.phone))return;const o=get(h.sid);if(!o.cr){o.cr=h.ts;o.phone=h.phone}if(!o.cits.some(z=>z.t===t&&z.mt===h.mt))o.cits.push({t,mt:h.mt});if(!o.snip)o.snip=plain(h.tx)});
