  const itemTxt=o=>nz([o.agent,o.team,o.tag,o.poll,o.snip,o.kws.join(" "),o.perdas.map(p=>p.r.plate+" "+p.r.name).join(" "),o.cits.map(c=>c.t.title).join(" ")].join(" "));
