    const L=all.filter(o=>{if(U.f==="perda"&&!o.perdas.length)return false;if(U.f==="kw"&&!o.kws.length)return false;if(U.f==="cit"&&!o.cits.length)return false;
      if(q&&!(itemTxt(o).includes(q)||(qd.length>=4&&(o.phone.includes(qd)||o.perdas.some(p=>(p.r.cpf||"").includes(qd)||p.r.tels.some(t=>t.raw.includes(qd)))))))return false;return true});
